{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Cromolyn, a chromone/coumarin-like drug, has systemic bioavailability of approximately 1% in healthy volunteers after oral administration, supporting low oral bioavailability for the coumarin-related query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Bazedoxifene has an absolute oral bioavailability of about 6% in healthy postmenopausal women, indicating that phenolic drug-like molecules with extensive first-pass metabolism can have F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Resveratrol, a small phenolic compound, has human oral bioavailability below 1% due to extensive intestinal and hepatic metabolism; the query shares phenolic and small aromatic features, supporting a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Naringenin, a phenolic flavanone, shows human oral bioavailability of about 5.8-15%, below the 20% threshold, supporting low F for small phenolic compounds subject to conjugation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Fenoterol, a phenolic drug, has approximately 2% oral bioavailability in humans due to extensive presystemic sulfation; the query's phenolic hydroxyl may undergo similar phase II conjugation, supporting low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to low oral bioavailability (<20%) for the query: structurally related phenolic and coumarin-like molecules show human F values of approximately 1-15%, with extensive first-pass phase II metabolism. No evidence supports F ≥ 20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability study for 4-methylumbelliferone (the query) is available.",
    "Most evidence comes from polyphenols/flavonoids or highly polar drugs rather than simple coumarins, so the exact extent of first-pass metabolism for this specific coumarin is uncertain.",
    "Some coumarins, such as warfarin, have high oral bioavailability, creating uncertainty about whether the coumarin scaffold alone would overcome phase II conjugation liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

